+    const dest = path.join(destDir, file);
+    if (filesIdentical(src, dest)) continue;
+    fs.mkdirSync(path.dirname(dest), { recursive: true });
+    fs.copyFileSync(src, dest);
+    copied += 1;
+  }
+  return { copied, missingTemplate: false };
+}
